prompt.text:
Repair the implementation below and return one complete CommonJS source file.

`decodeFrames(bytes)` decodes a `Uint8Array` containing consecutive length-prefixed frames. Each frame begins with an unsigned two-byte big-endian payload length followed by exactly that many payload bytes. A zero-length frame is valid. An empty input is valid and yields no frames.

On success return `{ ok: true, frames }`, where every frame is a newly allocated `Uint8Array`. If the input is not a `Uint8Array`, if fewer than two bytes remain for a header, or if a payload is truncated, return `{ ok: false, error: 'Malformed frames', frames: [] }` and discard any frames decoded earlier. Do not mutate or alias the input.

Export exactly `{ decodeFrames }`.

```javascript
'use strict';

function decodeFrames(bytes) {
  if (!(bytes instanceof Uint8Array)) {
    return { ok: false, error: 'Malformed frames', frames: [] };
  }

  const frames = [];
  let offset = 0;
  while (offset < bytes.length) {
    if (bytes.length - offset < 2) {
      return { ok: false, error: 'Malformed frames', frames: [] };
    }

    const length = bytes[offset] | (bytes[offset + 1] << 8);
    offset += 2;
    if (bytes.length - offset < length) {
      return { ok: false, error: 'Malformed frames', frames: [] };
    }

    frames.push(bytes.slice(offset, offset + length));
    offset += length;
  }

  return { ok: true, frames };
}

module.exports = { decodeFrames };
```

