'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['decodeFrames']);
const { decodeFrames } = api;

assert.deepStrictEqual(decodeFrames(new Uint8Array()), { ok: true, frames: [] });
for (const bad of [null, [], new ArrayBuffer(2), new DataView(new ArrayBuffer(2))]) {
  assert.deepStrictEqual(decodeFrames(bad), { ok: false, error: 'Malformed frames', frames: [] });
}
assert.deepStrictEqual(decodeFrames(new Uint8Array([0])), { ok: false, error: 'Malformed frames', frames: [] });
assert.deepStrictEqual(decodeFrames(new Uint8Array([0, 2, 7])), { ok: false, error: 'Malformed frames', frames: [] });
assert.deepStrictEqual(decodeFrames(new Uint8Array([0, 1, 9, 0])), { ok: false, error: 'Malformed frames', frames: [] });

const input = new Uint8Array([0, 0, 0, 3, 1, 2, 3, 1, 0, ...new Uint8Array(256).fill(7)]);
const snapshot = new Uint8Array(input);
const result = decodeFrames(input);
assert.strictEqual(result.ok, true);
assert.strictEqual(result.frames.length, 3);
assert.deepStrictEqual(Array.from(result.frames[0]), []);
assert.deepStrictEqual(Array.from(result.frames[1]), [1, 2, 3]);
assert.strictEqual(result.frames[2].length, 256);
assert.strictEqual(result.frames[2][0], 7);
assert.deepStrictEqual(input, snapshot);
assert.notStrictEqual(result.frames[0], input);
assert.notStrictEqual(result.frames[1].buffer, input.buffer);
result.frames[1][0] = 99;
assert.strictEqual(input[4], 1);
const again = decodeFrames(input);
assert.strictEqual(again.frames[1][0], 1);
assert.notStrictEqual(result.frames, again.frames);
assert.notStrictEqual(result.frames[1], again.frames[1]);

